public class ScoreSerializerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            byte[] bytes = ScoreSerializer.toBytes(new Score("Ana", 42));
            check("toBytes produces data", true, bytes != null && bytes.length > 0);
            Score back = ScoreSerializer.fromBytes(bytes);
            check("name survives the round trip", "Ana",
                    back == null ? "(no object)" : back.getName());
            check("points survive the round trip", 42,
                    back == null ? "(no object)" : back.getPoints());

            Score negative = ScoreSerializer.fromBytes(
                    ScoreSerializer.toBytes(new Score("Bo", -5)));
            check("negative points survive", -5,
                    negative == null ? "(no object)" : negative.getPoints());

            Score blank = ScoreSerializer.fromBytes(
                    ScoreSerializer.toBytes(new Score("", 0)));
            check("empty name survives", "",
                    blank == null ? "(no object)" : blank.getName());
            check("zero points survive", 0,
                    blank == null ? "(no object)" : blank.getPoints());
        } catch (Exception e) {
            check("round trip completes without exception", "none",
                    e.getClass().getSimpleName());
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

