class Score implements java.io.Serializable {
    private final String name;
    private final int points;

    Score(String name, int points) {
        this.name = name;
        this.points = points;
    }

    String getName() {
        return name;
    }

    int getPoints() {
        return points;
    }
}

public class ScoreSerializer {

    public static byte[] toBytes(Score s) throws java.io.IOException {
        java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream();
        try (java.io.ObjectOutputStream out = new java.io.ObjectOutputStream(bytes)) {
            out.writeObject(s);
        }
        return bytes.toByteArray();
    }

    public static Score fromBytes(byte[] b)
            throws java.io.IOException, ClassNotFoundException {
        try (java.io.ObjectInputStream in = new java.io.ObjectInputStream(
                new java.io.ByteArrayInputStream(b))) {
            return (Score) in.readObject();
        }
    }
}
